export const defaultPreferences={rarity_mode:'Same Rarity',trades_left_today:3};
export function preferencePatch(patch){const row={};if('rarity_mode' in patch){const m=patch.rarity_mode;if(!['Same Rarity','Any Rarity','Flexible Rarity','No Trading'].includes(m))throw Error('Invalid trade setting.');Object.assign(row,{rarity_mode:m,accept_equal:m==='Same Rarity'||m==='Flexible Rarity',accept_up:m==='Flexible Rarity',accept_down:m==='Flexible Rarity',accept_any:m==='Any Rarity'})}if('trades_left_today' in patch){if(!Number.isInteger(patch.trades_left_today)||patch.trades_left_today<0||patch.trades_left_today>3)throw Error('Choose 0–3 attempts.');row.trades_left_today=patch.trades_left_today}return row}
